import React, { useState, useEffect } from 'react';
import logoImg from './logo.png';

function App() {
  // Controle de Navegação Interna: 'dashboard', 'bpm', 'sono', 'estresse', 'recomendacoes', 'agendar', 'emergencia'
  const [currentPage, setCurrentPage] = useState('dashboard');

  const [appointments, setAppointments] = useState([]);
  const [healthUnits, setHealthUnits] = useState([]);
  const [loading, setLoading] = useState(true);

  // Estados para inputs do usuário
  const [userStressReport, setUserStressReport] = useState('');
  const [savedStressReports, setSavedStressReports] = useState([]);
  const [emergencyContacts, setEmergencyContacts] = useState([
    { id: 1, nome: "SAMU", numero: "192" },
    { id: 2, nome: "Upa Local", numero: "(81) 3184-4100" },
    { id: 3, nome: "Contato de Confiança (Ana)", numero: "(81) 99999-5555" }
  ]);
  const [newAppointment, setNewAppointment] = useState({ tipo: 'Unidade Móvel', data: '', hora: '' });

  const [healthMetrics] = useState({
    bpm: 76,
    sono: "7h 20m",
    estresse: "Baixo",
    recomendacoes: "Ver Recomendações",
    iaRecommendation: "Seu nível de estresse reduziu 12% após a melhoria do sono. Excelente evolução! Continue mantendo a hidratação constante durante as rotas externas hoje."
  });

  // Dados históricos simulados para os gráficos de 7 dias
  const historyData = {
    bpm: [72, 75, 78, 82, 74, 76, 76],
    sono: [6.5, 7.0, 5.8, 7.2, 6.8, 7.3, 7.3],
    estresse: [20, 40, 60, 80, 30, 25, 20], // Porcentagem de intensidade
    dias: ['Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom', 'Seg']
  };

  useEffect(() => {
    Promise.all([
      fetch('http://localhost:8000/appointments').then(res => res.json()),
      fetch('http://localhost:8000/health-units').then(res => res.json())
    ])
    .then(([appointmentsData, unitsData]) => {
      setAppointments(appointmentsData);
      setHealthUnits(unitsData);
      setLoading(false);
    })
    .catch((err) => {
      console.error("Erro ao conectar com a API do Back-end:", err);
      setLoading(false);
    });
  }, []);

  const handleAddStressReport = (e) => {
    e.preventDefault();
    if (!userStressReport.trim()) return;
    setSavedStressReports([
      { data: new Date().toLocaleDateString('pt-BR'), texto: userStressReport },
      ...savedStressReports
    ]);
    setUserStressReport('');
    alert("Relato de estresse salvo com sucesso no seu histórico local!");
  };

  const handleSchedule = (e) => {
    e.preventDefault();
    if (!newAppointment.data || !newAppointment.hora) {
      alert("Por favor, preencha a data e o horário.");
      return;
    }
    const mockedNew = {
      id: appointments.length + 1,
      patient_name: "Eduardo Luz",
      appointment_type: newAppointment.tipo,
      date_time: `${newAppointment.data} ${newAppointment.hora}`,
      status: "Agendado"
    };
    setAppointments([mockedNew, ...appointments]);
    alert("Consulta agendada com sucesso!");
    setCurrentPage('dashboard');
  };

  return (
    <div style={styles.body}>
      {/* Barra de Navegação Superior */}
      <header style={styles.navbar}>
        <div style={styles.brandContainer} onClick={() => setCurrentPage('dashboard')} style={{...styles.brandContainer, cursor: 'pointer'}}>
          <div style={styles.logoContainer}>
            <img src={logoImg} alt="Logo Saúde Para Todos" style={styles.logoImage} />
          </div>
          <h1 style={styles.navTitle}>Saúde Para Todos</h1>
        </div>
        <div style={styles.navLinks}>
          <span style={styles.userBadge}>Painel do Usuário</span>
          {currentPage !== 'dashboard' && (
            <button style={styles.backButton} onClick={() => setCurrentPage('dashboard')}>⬅ Voltar ao Painel</button>
          )}
        </div>
      </header>

      <div style={styles.mainContainer}>

        {/* VIEW PRINCIPAL: DASHBOARD */}
        {currentPage === 'dashboard' && (
          <>
            <section style={styles.leftColumn}>
              {/* Seção Inteligência Artificial */}
              <div style={styles.iaCard}>
                <div style={styles.iaHeader}>
                  <span style={{ fontSize: '20px' }}>✨</span>
                  <h3 style={styles.iaTitle}>Recomendações Personalizadas de IA</h3>
                </div>
                <p style={styles.iaText}>{healthMetrics.iaRecommendation}</p>
              </div>

              {/* Módulo Health Sync Interativo */}
              <h2 style={styles.sectionHeading}>Saúde Para Todos — Métricas Ativas (Clique para Ver Detalhes)</h2>
              <div style={styles.metricsGrid}>

                {/* Card Batimentos */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('bpm')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#e53e3e" }}>❤️</span>
                    <span style={styles.metricLabel}>Batimentos Cardíacos</span>
                  </div>
                  <p style={styles.metricValue}>{healthMetrics.bpm} <span style={styles.metricUnit}>BPM</span></p>
                  <span style={styles.metricStatusStable}>Ver Histórico ➔</span>
                </div>

                {/* Card Sono */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('sono')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#3182ce" }}>🌙</span>
                    <span style={styles.metricLabel}>Monitoramento do Sono</span>
                  </div>
                  <p style={styles.metricValue}>{healthMetrics.sono}</p>
                  <span style={styles.metricStatusStable}>Ver Histórico ➔</span>
                </div>

                {/* Card Estresse */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('estresse')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#dd6b20" }}>⚡</span>
                    <span style={styles.metricLabel}>Nível de Estresse</span>
                  </div>
                  <p style={styles.metricValue}>{healthMetrics.estresse}</p>
                  <span style={styles.metricStatusStable}>Relatar Dia ➔</span>
                </div>

                {/* Card Recomendações */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('recomendacoes')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#319795" }}>📜</span>
                    <span style={styles.metricLabel}>Recomendações</span>
                  </div>
                  <p style={styles.metricValue}>Análise IA</p>
                  <span style={styles.metricStatusStable}>Ver Relatório ➔</span>
                </div>

                {/* Card Agendar Consulta */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('agendar')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#4a5568" }}>✍️</span>
                    <span style={styles.metricLabel}>Agendar Consulta</span>
                  </div>
                  <p style={styles.metricValue}>Marcar</p>
                  <span style={styles.metricStatusStable}>Abrir Agenda ➔</span>
                </div>

                {/* Card Emergência */}
                <div style={styles.clickableCard} onClick={() => setCurrentPage('emergencia')}>
                  <div style={styles.metricHeader}>
                    <span style={{ fontSize: "22px", color: "#e53e3e" }}>🚨</span>
                    <span style={styles.metricLabel}>Emergência</span>
                  </div>
                  <p style={styles.metricValue}>Contatos</p>
                  <span style={styles.metricStatusEmergency}>Ligar Agora ➔</span>
                </div>

              </div>
            </section>

            <section style={styles.rightColumn}>
              <h2 style={styles.sectionHeading}>Unidades Móveis em Operação</h2>
              <div style={styles.unitsList}>
                {loading ? <p>Carregando unidades...</p> : healthUnits.map(unit => (
                  <div key={unit.id} style={styles.unitItem}>
                    <div>
                      <h4 style={styles.unitName}>🚐 {unit.name}</h4>
                      <p style={styles.unitLocation}>{unit.location}</p>
                    </div>
                    <span style={styles.activeBadge}>{unit.status}</span>
                  </div>
                ))}
              </div>

              <h2 style={styles.sectionHeading}><br/>Seus Agendamentos de Consultas</h2>
              <div style={styles.tableWrapper}>
                <table style={styles.table}>
                  <thead>
                    <tr style={styles.tableHeaderRow}>
                      <th style={styles.tableTh}>Paciente</th>
                      <th style={styles.tableTh}>Atendimento</th>
                      <th style={styles.tableTh}>Data/Hora</th>
                      <th style={styles.tableTh}>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {appointments.map((app) => (
                      <tr key={app.id} style={styles.tableRow}>
                        <td style={styles.patientNameTd}>{app.patient_name}</td>
                        <td style={styles.tableTd}>{app.appointment_type}</td>
                        <td style={styles.tableTd}>{app.date_time}</td>
                        <td style={styles.tableTd}><span style={styles.statusPill}>{app.status}</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          </>
        )}

        {/* PÁGINA: BATIMENTOS CARDÍACOS */}
        {currentPage === 'bpm' && (
          <div style={styles.fullWidthView}>
            <h2>❤️ Histórico de Batimentos Cardíacos (Últimos 7 dias)</h2>
            <p>Análise de estabilidade baseada nos dados do seu dispositivo ou coletas em Unidades Móveis.</p>

            <div style={styles.chartContainer}>
              {historyData.bpm.map((value, i) => (
                <div key={i} style={styles.chartBarWrapper}>
                  <div style={{...styles.chartBar, height: `${value * 2}px`, backgroundColor: '#e53e3e'}} />
                  <span style={styles.chartBarLabel}>{value} BPM</span>
                  <span style={styles.chartBarDay}>{historyData.dias[i]}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* PÁGINA: MONITORAMENTO DO SONO */}
        {currentPage === 'sono' && (
          <div style={styles.fullWidthView}>
            <h2>🌙 Histórico de Monitoramento do Sono (Últimos 7 dias)</h2>
            <p>Média ideal recomendada de descanso: 7h a 8h por noite.</p>

            <div style={styles.chartContainer}>
              {historyData.sono.map((value, i) => (
                <div key={i} style={styles.chartBarWrapper}>
                  <div style={{...styles.chartBar, height: `${value * 25}px`, backgroundColor: '#3182ce'}} />
                  <span style={styles.chartBarLabel}>{value}h</span>
                  <span style={styles.chartBarDay}>{historyData.dias[i]}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* PÁGINA: NÍVEL DE ESTRESSE */}
        {currentPage === 'estresse' && (
          <div style={styles.fullWidthView}>
            <h2>⚡ Gerenciamento de Estresse e Diário Emocional</h2>

            <div style={styles.chartContainer}>
              {historyData.estresse.map((value, i) => (
                <div key={i} style={styles.chartBarWrapper}>
                  <div style={{...styles.chartBar, height: `${value * 2}px`, backgroundColor: '#dd6b20'}} />
                  <span style={styles.chartBarLabel}>{value}%</span>
                  <span style={styles.chartBarDay}>{historyData.dias[i]}</span>
                </div>
              ))}
            </div>

            <div style={styles.formSection}>
              <h3>✍️ Relate como foi seu dia ou situações estressantes</h3>
              <form onSubmit={handleAddStressReport}>
                <textarea
                  style={styles.textarea}
                  placeholder="Escreva aqui como você se sente hoje..."
                  value={userStressReport}
                  onChange={(e) => setUserStressReport(e.target.value)}
                />
                <button type="submit" style={styles.submitButton}>Salvar no meu Prontuário</button>
              </form>
            </div>

            {savedStressReports.length > 0 && (
              <div style={{ marginTop: '20px' }}>
                <h4>Histórico de Relatos:</h4>
                {savedStressReports.map((item, idx) => (
                  <div key={idx} style={styles.reportItem}>
                    <strong>{item.data}</strong> — {item.texto}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* PÁGINA: RECOMENDAÇÕES DA IA */}
        {currentPage === 'recomendacoes' && (
          <div style={styles.fullWidthView}>
            <h2>📜 Relatório Automatizado de Qualidade de Vida (IA)</h2>
            <div style={styles.iaCard}>
              <p style={{fontSize: '16px', lineHeight: '1.6'}}>
                <strong>Cruzamento de Dados Ativos:</strong><br/>
                Analisando a sua média de <strong>7.1 horas de sono</strong> aliada a uma frequência cardíaca de repouso estável em <strong>76 BPM</strong>, identificamos que seus picos de estresse estão concentrados em períodos de trânsito ou alta atividade externa.
              </p>
              <hr style={{border: '0', borderBottom: '1px solid #e2e8f0', margin: '20px 0'}} />
              <h3>✨ Plano de Ação Personalizado da Inteligência Artificial:</h3>
              <ul style={{lineHeight: '2', fontSize: '15px'}}>
                <li>🥗 <strong>Nutrição Adaptada:</strong> Aumente o consumo de alimentos ricos em magnésio e potássio no jantar para estender o sono profundo.</li>
                <li>💧 <strong>Hidratação nas Rotas:</strong> Mantenha consumo constante de água mineral enquanto acompanha as rotas das Unidades Móveis.</li>
                <li>🧘‍♂️ <strong>Exercício de Respiração:</strong> Realize 3 ciclos de respiração diafragmática ao identificar alertas de nível de estresse moderado.</li>
              </ul>
            </div>
          </div>
        )}

        {/* PÁGINA: AGENDAR CONSULTA */}
        {currentPage === 'agendar' && (
          <div style={styles.fullWidthView}>
            <h2>✍️ Sistema de Marcação e Triagem Preventiva</h2>
            <p>Selecione o local e o melhor dia para o seu atendimento humanizado presencial.</p>

            <div style={styles.formSection}>
              <form onSubmit={handleSchedule} style={{ display: 'flex', flexDirection: 'column', gap: '15px', maxWidth: '400px' }}>
                <label>
                  <strong>Tipo de Local de Atendimento:</strong>
                  <select
                    style={styles.input}
                    value={newAppointment.tipo}
                    onChange={(e) => setNewAppointment({...newAppointment, tipo: e.target.value})}
                  >
                    <option value="Unidade Móvel Zonas Periféricas">🚐 Unidade Móvel Zonas Periféricas</option>
                    <option value="UBS Central">🏥 UBS Central</option>
                    <option value="Atendimento Domiciliar">🏡 Atendimento Domiciliar</option>
                  </select>
                </label>

                <label>
                  <strong>Selecione a Data:</strong>
                  <input
                    type="date"
                    style={styles.input}
                    value={newAppointment.data}
                    onChange={(e) => setNewAppointment({...newAppointment, data: e.target.value})}
                  />
                </label>

                <label>
                  <strong>Horário Disponível:</strong>
                  <input
                    type="time"
                    style={styles.input}
                    value={newAppointment.hora}
                    onChange={(e) => setNewAppointment({...newAppointment, hora: e.target.value})}
                  />
                </label>

                <button type="submit" style={styles.submitButton}>Confirmar Agendamento</button>
              </form>
            </div>
          </div>
        )}

        {/* PÁGINA: EMERGÊNCIA */}
        {currentPage === 'emergencia' && (
          <div style={styles.fullWidthView}>
            <h2>🚨 Central de Contatos de Emergência</h2>
            <p>Clique em qualquer um dos números abaixo para efetuar chamadas diretas imediatas.</p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' }}>
              {emergencyContacts.map(contact => (
                <div key={contact.id} style={styles.emergencyContactCard}>
                  <div>
                    <h3 style={{ margin: 0, color: '#e53e3e' }}>{contact.nome}</h3>
                    <p style={{ margin: '5px 0 0 0', fontSize: '18px', fontWeight: 'bold' }}>{contact.numero}</p>
                  </div>
                  <button
                    style={styles.callButton}
                    onClick={() => alert(`Simulando discagem para o número ${contact.numero}...`)}
                  >
                    📞 Ligar Agora
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

const styles = {
  body: {
    fontFamily: '"Segoe UI", Roboto, Helvetica, Arial, sans-serif',
    backgroundColor: '#f3f7f7',
    minHeight: '100vh',
    margin: 0,
    color: '#2d3748',
  },
  navbar: {
    backgroundColor: '#1a5f60',
    padding: '12px 30px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    color: '#ffffff',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
  },
  brandContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '15px',
  },
  logoContainer: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  logoImage: {
    height: '45px',
    width: 'auto',
    objectFit: 'contain',
  },
  navTitle: {
    margin: 0,
    fontSize: '22px',
    fontWeight: '600',
  },
  navLinks: {
    display: 'flex',
    alignItems: 'center',
    gap: '20px',
  },
  userBadge: {
    backgroundColor: 'rgba(255,255,255,0.15)',
    padding: '5px 12px',
    borderRadius: '20px',
    fontSize: '13px',
  },
  backButton: {
    backgroundColor: '#2b9393',
    border: 'none',
    color: '#ffffff',
    padding: '8px 16px',
    borderRadius: '4px',
    cursor: 'pointer',
    fontWeight: 'bold',
  },
  mainContainer: {
    display: 'flex',
    gap: '30px',
    padding: '30px',
    maxWidth: '1400px',
    margin: '0 auto',
    flexWrap: 'wrap',
  },
  leftColumn: {
    flex: '1 1 500px',
    display: 'flex',
    flexDirection: 'column',
    gap: '20px',
  },
  rightColumn: {
    flex: '1 1 500px',
    display: 'flex',
    flexDirection: 'column',
    gap: '20px',
  },
  sectionHeading: {
    fontSize: '18px',
    color: '#1a5f60',
    margin: '0 0 5px 0',
    borderBottom: '2px solid #e2e8f0',
    paddingBottom: '6px',
  },
  iaCard: {
    backgroundColor: '#ffffff',
    borderLeft: '5px solid #2b9393',
    borderRadius: '8px',
    padding: '20px',
    boxShadow: '0 4px 6px rgba(0,0,0,0.02)',
  },
  iaHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    marginBottom: '10px',
  },
  iaTitle: {
    margin: 0,
    color: '#1a5f60',
    fontSize: '16px',
    fontWeight: '600',
  },
  iaText: {
    margin: 0,
    fontSize: '14px',
    color: '#4a5568',
    lineHeight: '1.5',
    textAlign: 'justify',
  },
  metricsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '15px',
  },
  clickableCard: {
    backgroundColor: '#ffffff',
    borderRadius: '8px',
    padding: '18px',
    boxShadow: '0 2px 5px rgba(0,0,0,0.03)',
    cursor: 'pointer',
    transition: 'transform 0.15s ease, box-shadow 0.15s ease',
    border: '1px solid transparent',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
